-- V147 — El borrador del diagnóstico del dueño (spec 026; D-303)
--
-- Por qué se toca la base
-- -----------------------
-- El diagnóstico reemplaza al Mapa de Renacimiento y el dueño ya tiene su formulario hecho (su Google Form «Diagnóstico inicial»).
-- Esta migración carga sus preguntas como el flujo `diagnostico` del motor de onboarding, EN BORRADOR: nada llega a las personas hasta que Administración lo revise y lo publique desde
-- la app (Administración → Fichas). Es el mismo contenido de `specs/026-ficha-con-diagnostico/diagnostico-inicial.csv`, con las adaptaciones del anexo: la edad como número, cada
-- resultado (16 a 18) partido en «hoy» y «en {duracion}», los plazos con la marca `{duracion}` (se reemplaza por «90 días» o «1 año» según la persona), y la pregunta del trato (Q7-A).
--
-- Por qué no tablas ni código nuevo
-- ---------------------------------
-- Son filas de las tablas que ya existen (V1, ampliadas en V144). La declaración de responsabilidad y consentimiento (pregunta 23) NO está en el formulario: queda un texto de relleno marcado
-- `[PENDIENTE DEL DUEÑO]` y el diagnóstico NO se puede publicar mientras siga así (decisión 026-6). Solo se siembra si el flujo está vacío, así que reaplicar no duplica nada.

SET search_path TO renaser, public;

DO $semilla$
BEGIN
    IF EXISTS (SELECT 1 FROM secciones_onboarding WHERE flujo = 'diagnostico') THEN
        RETURN;
    END IF;

No buscamos respuestas perfectas. Buscamos respuestas verdaderas.', 0);
    VALUES ((SELECT id FROM secciones_onboarding WHERE flujo = 'diagnostico' AND clave_seccion = 'conociendote'), 'diag_p1', '¿Cuál es tu nombre completo?', 'TEXTO', NULL, true, 0, NULL, NULL, NULL, NULL, NULL, 'NOMBRE_COMPLETO');
    VALUES ((SELECT id FROM secciones_onboarding WHERE flujo = 'diagnostico' AND clave_seccion = 'conociendote'), 'diag_ptrato', '¿Cómo prefieres que nos dirijamos a ti?', 'SELECCION_UNICA', NULL, true, 1, NULL, 'Lo usamos para hablarte bien en los avisos y en tu acompañante SER.', NULL, NULL, 'TRATO_DE_LA_PERSONA', NULL);
    VALUES ((SELECT id FROM secciones_onboarding WHERE flujo = 'diagnostico' AND clave_seccion = 'conociendote'), 'diag_p2', '¿Cuántos años tienes?', 'NUMERO', NULL, true, 2, NULL, NULL, NULL, NULL, NULL, NULL);
    VALUES ((SELECT id FROM secciones_onboarding WHERE flujo = 'diagnostico' AND clave_seccion = 'conociendote'), 'diag_p3', '¿En qué ciudad y país resides?', 'TEXTO', NULL, true, 3, NULL, NULL, NULL, NULL, NULL, NULL);
    VALUES ((SELECT id FROM secciones_onboarding WHERE flujo = 'diagnostico' AND clave_seccion = 'conociendote'), 'diag_p4', '¿A qué te dedicas actualmente?', 'SELECCION_UNICA', NULL, true, 4, NULL, NULL, NULL, NULL, NULL, NULL);
    VALUES ((SELECT id FROM secciones_onboarding WHERE flujo = 'diagnostico' AND clave_seccion = 'tu_vida_hoy'), 'diag_p5', '¿Qué tan satisfecho(a) estás con los resultados que obtienes actualmente en estas áreas?', 'CUADRICULA', '{"min":1,"max":5,"etiquetaMin":"Muy insatisfecho(a)","etiquetaMax":"Muy satisfecho(a)"}'::jsonb, true, 0, NULL, 'Escala del 1 al 5: 1 = Muy insatisfecho(a). 5 = Muy satisfecho(a).
Selecciona una respuesta por área.', NULL, NULL, NULL, NULL);
    VALUES ((SELECT id FROM secciones_onboarding WHERE flujo = 'diagnostico' AND clave_seccion = 'tu_vida_hoy'), 'diag_p6', 'En tus relaciones personales, familiares o profesionales, ¿qué situación te gustaría mejorar principalmente?', 'SELECCION_UNICA', NULL, true, 1, NULL, NULL, NULL, NULL, NULL, NULL);
    VALUES ((SELECT id FROM secciones_onboarding WHERE flujo = 'diagnostico' AND clave_seccion = 'tu_vida_hoy'), 'diag_p7', 'Durante los últimos siete días, ¿cuántas horas dormiste en promedio por noche?', 'SELECCION_UNICA', NULL, true, 2, NULL, NULL, NULL, NULL, NULL, NULL);
    VALUES ((SELECT id FROM secciones_onboarding WHERE flujo = 'diagnostico' AND clave_seccion = 'tu_vida_hoy'), 'diag_p8', 'Durante los últimos siete días, ¿cuántos días realizaste por lo menos 30 minutos de actividad física o movimiento intencional?', 'SELECCION_UNICA', NULL, true, 3, NULL, NULL, NULL, NULL, NULL, NULL);
    VALUES ((SELECT id FROM secciones_onboarding WHERE flujo = 'diagnostico' AND clave_seccion = 'tu_vida_hoy'), 'diag_p9', '¿Qué aspecto está afectando más tu salud, energía o bienestar actualmente?', 'SELECCION_UNICA', NULL, true, 4, NULL, NULL, NULL, NULL, NULL, NULL);
    VALUES ((SELECT id FROM secciones_onboarding WHERE flujo = 'diagnostico' AND clave_seccion = 'tu_vida_hoy'), 'diag_p10', '¿Cuál es tu ingreso personal mensual promedio actual?', 'TEXTO', NULL, true, 5, NULL, 'Considera lo que recibiste personalmente durante los últimos tres meses, sumando tus fuentes de ingreso. Indica monto y moneda.
Ejemplo: S/ 30000 o US$ 7000', NULL, NULL, NULL, NULL);
    VALUES ((SELECT id FROM secciones_onboarding WHERE flujo = 'diagnostico' AND clave_seccion = 'tu_vida_hoy'), 'diag_p11', '¿Qué situación describe mejor tu realidad económica actual?', 'SELECCION_UNICA', NULL, true, 6, NULL, NULL, NULL, NULL, NULL, NULL);
    VALUES ((SELECT id FROM secciones_onboarding WHERE flujo = 'diagnostico' AND clave_seccion = 'tu_vida_hoy'), 'diag_p12', '¿Cuántas horas dedicas semanalmente a tu trabajo, negocio o actividad profesional?', 'SELECCION_UNICA', NULL, true, 7, NULL, NULL, NULL, NULL, NULL, NULL);
    VALUES ((SELECT id FROM secciones_onboarding WHERE flujo = 'diagnostico' AND clave_seccion = 'tu_vida_hoy'), 'diag_p13', '¿Actualmente tienes un negocio o actividad independiente que ya genera ventas?', 'SELECCION_UNICA', NULL, true, 8, NULL, NULL, NULL, NULL, NULL, NULL);
    VALUES ((SELECT id FROM secciones_onboarding WHERE flujo = 'diagnostico' AND clave_seccion = 'tu_negocio'), 'diag_p13a', '¿A qué se dedica tu negocio?', 'TEXTO', NULL, false, 0, (SELECT id FROM preguntas_onboarding WHERE clave_pregunta = 'diag_p13'), NULL, NULL, 'Sí.', NULL, NULL);
    VALUES ((SELECT id FROM secciones_onboarding WHERE flujo = 'diagnostico' AND clave_seccion = 'tu_negocio'), 'diag_p13b', '¿Cuánto factura mensualmente, en promedio, tu negocio?', 'TEXTO', NULL, false, 1, (SELECT id FROM preguntas_onboarding WHERE clave_pregunta = 'diag_p13'), 'Indica las ventas totales antes de descontar gastos. Coloca monto y moneda. Considera el promedio de los últimos tres meses.', NULL, 'Sí.', NULL, NULL);
    VALUES ((SELECT id FROM secciones_onboarding WHERE flujo = 'diagnostico' AND clave_seccion = 'tu_negocio'), 'diag_p13c', '¿Cuál es la utilidad neta mensual aproximada de tu negocio?', 'TEXTO', NULL, false, 2, (SELECT id FROM preguntas_onboarding WHERE clave_pregunta = 'diag_p13'), 'Es el dinero que queda después de pagar los gastos del negocio. Si no lo conoces, escribe «No lo sé».', NULL, 'Sí.', NULL, NULL);
    VALUES ((SELECT id FROM secciones_onboarding WHERE flujo = 'diagnostico' AND clave_seccion = 'tu_negocio'), 'diag_p13d', '¿Cuántas personas trabajan actualmente en tu negocio, sin incluirte?', 'TEXTO', NULL, false, 3, (SELECT id FROM preguntas_onboarding WHERE clave_pregunta = 'diag_p13'), NULL, NULL, 'Sí.', NULL, NULL);
    VALUES ((SELECT id FROM secciones_onboarding WHERE flujo = 'diagnostico' AND clave_seccion = 'tu_mente'), 'diag_p14', 'Cuando sabes que necesitas hacer algo importante, pero terminas sin hacerlo, ¿qué suele ocurrir?', 'SELECCION_MULTIPLE', NULL, false, 0, NULL, 'Selecciona como máximo 2 respuestas.', 2, NULL, NULL, NULL);
    VALUES ((SELECT id FROM secciones_onboarding WHERE flujo = 'diagnostico' AND clave_seccion = 'tu_mente'), 'diag_p15', 'Piensa en una situación real de los últimos 30 días en la que no hayas actuado como querías. ¿Qué ocurrió, cómo reaccionaste y cuál fue el resultado?', 'AREA_TEXTO', NULL, true, 1, NULL, 'Responde en dos o tres frases. Puede ser una situación relacionada con tu negocio, pareja, familia, dinero, trabajo o contigo mismo(a). Si no recuerdas alguna, puedes indicarlo.
Ejemplo:
«Tenía que conversar con un colaborador sobre un problema. Evité hacerlo porque no quería generar un conflicto. El problema continuó y terminó afectando el trabajo del equipo».', NULL, NULL, NULL, NULL);
    VALUES ((SELECT id FROM secciones_onboarding WHERE flujo = 'diagnostico' AND clave_seccion = 'tu_vision'), 'diag_p16a', 'RELACIONES · Hoy mi situación es…', 'AREA_TEXTO', NULL, true, 0, NULL, '¿Cómo está hoy esto en tu vida? Ejemplo: Hoy evito conversaciones importantes con mi pareja.', NULL, NULL, NULL, NULL);
    VALUES ((SELECT id FROM secciones_onboarding WHERE flujo = 'diagnostico' AND clave_seccion = 'tu_vision'), 'diag_p16b', 'RELACIONES · ¿Qué resultado concreto quieres conseguir en tus relaciones en {duracion}?', 'AREA_TEXTO', NULL, true, 1, NULL, 'Escribe lo que quieres haber conseguido al final de tu programa. Ejemplo: En {duracion} quiero comunicarme con mayor claridad y sostener una conversación importante cada semana sin evitarla.', NULL, NULL, 'OBJETIVO_RELACIONES', NULL);
    VALUES ((SELECT id FROM secciones_onboarding WHERE flujo = 'diagnostico' AND clave_seccion = 'tu_vision'), 'diag_p17a', 'SALUD Y BIENESTAR · Hoy mi situación es…', 'AREA_TEXTO', NULL, true, 2, NULL, '¿Cómo está hoy esto en tu vida? Ejemplo: Hoy hago ejercicio una vez por semana.', NULL, NULL, NULL, NULL);
    VALUES ((SELECT id FROM secciones_onboarding WHERE flujo = 'diagnostico' AND clave_seccion = 'tu_vision'), 'diag_p17b', 'SALUD Y BIENESTAR · ¿Qué resultado concreto quieres conseguir en tu salud, energía o hábitos en {duracion}?', 'AREA_TEXTO', NULL, true, 3, NULL, 'Escribe lo que quieres haber conseguido al final de tu programa. Ejemplo: En {duracion} quiero realizar actividad física cuatro días por semana y mantener esa constancia.', NULL, NULL, 'OBJETIVO_CUERPO', NULL);
    VALUES ((SELECT id FROM secciones_onboarding WHERE flujo = 'diagnostico' AND clave_seccion = 'tu_vision'), 'diag_p18a', 'RIQUEZA Y NEGOCIOS · Hoy mi situación es…', 'AREA_TEXTO', NULL, true, 4, NULL, '¿Cómo está hoy esto en tu vida? Ejemplo: Actualmente mi negocio factura S/ 10,000 mensuales, con S/ 1,500 de utilidad.', NULL, NULL, NULL, NULL);
    VALUES ((SELECT id FROM secciones_onboarding WHERE flujo = 'diagnostico' AND clave_seccion = 'tu_vision'), 'diag_p18b', 'RIQUEZA Y NEGOCIOS · ¿Qué resultado concreto quieres conseguir económico, profesional o empresarial en {duracion}?', 'AREA_TEXTO', NULL, true, 5, NULL, 'Escribe lo que quieres haber conseguido al final de tu programa. Ejemplo: En {duracion} quiero facturar S/ 15,000 mensuales y alcanzar S/ 3,000 de utilidad.
Si aún no tienes negocio, puedes definir una meta de ingresos, ahorro, profesión o desarrollo de un proyecto.
Si no tienes claridad sobre alguno de tus objetivos, escribe «Necesito definirlo».', NULL, NULL, 'OBJETIVO_NEGOCIO', NULL);
    VALUES ((SELECT id FROM secciones_onboarding WHERE flujo = 'diagnostico' AND clave_seccion = 'tu_vision'), 'diag_p19', 'De las tres áreas anteriores, ¿cuál es tu prioridad principal durante los primeros {duracion} de RENASER?', 'SELECCION_UNICA', NULL, true, 6, NULL, NULL, NULL, NULL, 'PRIORIDAD_PRINCIPAL', NULL);
    VALUES ((SELECT id FROM secciones_onboarding WHERE flujo = 'diagnostico' AND clave_seccion = 'tu_vision'), 'diag_p20', 'Imagina que han transcurrido 12 meses y has aprovechado plenamente tu formación en RENASER. ¿Qué tendría que haber cambiado en tu vida para que sientas que has construido algo realmente valioso?', 'AREA_TEXTO', NULL, true, 7, NULL, 'Piensa en la persona que deseas llegar a ser, los resultados que quieres conseguir, la vida que quieres construir y aquello para lo que deseas utilizar tus capacidades y recursos.', NULL, NULL, NULL, NULL);
    VALUES ((SELECT id FROM secciones_onboarding WHERE flujo = 'diagnostico' AND clave_seccion = 'de_la_decision_a_la_accion'), 'diag_p21', '¿Qué primera acción concreta puedes realizar durante los próximos siete días para acercarte a tu objetivo principal?', 'TEXTO', NULL, true, 0, NULL, 'Indica qué harás y cuándo.
Ejemplo: «El lunes revisaré las finanzas de mi negocio para identificar mis tres gastos principales».', NULL, NULL, 'PRIMERA_ACCION', NULL);
    VALUES ((SELECT id FROM secciones_onboarding WHERE flujo = 'diagnostico' AND clave_seccion = 'de_la_decision_a_la_accion'), 'diag_p22', '¿Cuánto tiempo puedes dedicar semanalmente a tu formación y a aplicar lo aprendido?', 'SELECCION_UNICA', NULL, true, 1, NULL, NULL, NULL, NULL, NULL, NULL);
    VALUES ((SELECT id FROM secciones_onboarding WHERE flujo = 'diagnostico' AND clave_seccion = 'de_la_decision_a_la_accion'), 'diag_p23', 'Declaración de responsabilidad y consentimiento', 'CASILLA', NULL, true, 2, NULL, '[PENDIENTE DEL DUEÑO] Aquí va el texto de la declaración de responsabilidad y consentimiento. Administración debe reemplazarlo desde Administración → Fichas antes de publicar el diagnóstico.', NULL, NULL, NULL, NULL);
END
$semilla$;
